    const chunks:Buffer[]=[];let size=0;req.on('data',(chunk:Buffer)=>{size+=chunk.length;if(size>16384){req.destroy();return;}chunks.push(chunk);});req.on('end',()=>{try{const bytes=Buffer.concat(chunks),payload=JSON.parse(ece.decrypt(bytes,{version:'aes128gcm',privateKey:receiver,authSecret:auth}).toString('utf8'));const authorization=String(req.headers.authorization??''),match=authorization.match(/^vapid t=([A-Za-z0-9_.-]+), k=([A-Za-z0-9_-]+)$/),jwt=match?.[1].split('.')??[],key=Buffer.from(vapid.publicKey,'base64url');let valid=false;if(match?.[2]===vapid.publicKey&&jwt.length===3){const claims=JSON.parse(Buffer.from(jwt[1],'base64url').toString('utf8')),publicKey=createPublicKey({format:'jwk',key:{kty:'EC',crv:'P-256',x:key.subarray(1,33).toString('base64url'),y:key.subarray(33).toString('base64url')}});valid=claims.aud===pushOrigin&&claims.sub==='https://fg.invalid/push'&&claims.exp>Date.now()/1000&&claims.exp<Date.now()/1000+24*3600&&verify('sha256',Buffer.from(jwt[0]+'.'+jwt[1]),{key:publicKey,dsaEncoding:'ieee-p1363'},Buffer.from(jwt[2],'base64url'));}received.push({payload,encrypted:!bytes.includes(Buffer.from('Bạn có tin nhắn mới.')),vapid:valid});res.writeHead(responseStatus).end();}catch{res.writeHead(400).end();}finally{for(const chunk of chunks)chunk.fill(0);}});
